// The self-check for the Flisk Sales Architect task: a deterministic score from 0 to 100. The same repository state always gives
// the same score: no AI and no judgment, only counting what is in the candidate's PUBLIC GitHub repository. A person scores quality.
// It makes 5 GitHub API calls: 4 of the 60 an hour GitHub allows without a login, and 1 search of the 10 a minute.
const API = "https://api.github.com";
const RAW = "https://raw.githubusercontent.com";
const DAY = 864e5;
// Generated by flisk and ignored by its own .gitignore. .flisk/project.json is meant to be committed.
const GENERATED = /(^|\/)\.flisk\/(\.flisk-out|\.project-id|smoke)(\/|$)/;

export const READY_AT = 80;
export const STARTER = "flisk-sh/flisk-task-starter";
// Candidates fork the starter. Nobody should open an issue or pull request on these: the starter, Flisk, and the app it copies.
export const WATCHED = [STARTER, "flisk-sh/flisk", "flisk-sh/pages", "dockersamples/example-voting-app"];

// [key, group, label, max points]. The maximums add up to 100: technical 50, product 40, conduct 10.
export const ROWS = [
	["fork", "technical", "Part 1: a fork of flisk-sh/flisk-task-starter", 10],
	["stack", "technical", "Part 1: .flisk/project.json and one service.json per service (4 points each, 5 services)", 20],
	["readme", "technical", "Part 1: README shows flisk up and has a What was hard section of 3+ lines", 10],
	["license", "technical", "Part 1: the starter's LICENSE and NOTICE kept", 5],
	["clean", "technical", "Part 1: no .env, node_modules or generated .flisk files committed", 5],
	["vision", "product", "Part 2: ROADMAP.md has a ## Vision of 20+ words of your own", 5],
	["ice", "product", "Part 2: an ICE table under ## Next 6 months, 3 scored rows (5 points each)", 15],
	["math", "product", "Part 2: ICE = Impact × Confidence × Ease on every row (5) and sorted highest first (5)", 10],
	["watch", "product", "Part 2: a real Number to watch on every row", 5],
	["notnow", "product", "Part 2: ## Not now with a reason of 8+ words", 5],
	["crossrefs", "conduct", "Your commits link no other project's issues or pull requests (it would post on them)", 5],
	["contact", "conduct", "No issues or pull requests opened on the starter, Flisk or the original app since your start date", 5],
];
// Ready needs 80 or more AND these in full: a fork, no secrets, the licence kept, and no contact with other projects.
export const MUST = ["fork", "clean", "license", "crossrefs", "contact"];

/** The deadline: the end of the day two days after the start date (UTC). */
export function deadlineOf(start) {
	const t = Date.parse(`${start}T00:00:00Z`);
	return Number.isNaN(t) ? null : new Date(t + 3 * DAY - 1000);
}

/** The body under each "## " heading, keyed by the heading text. */
export function sections(md) {
	const out = [];
	for (const part of md.split(/^(?=##\s)/m)) {
		const m = /^##\s+([^\n]+)\n?([\s\S]*)$/.exec(part);
		if (m) out.push({ title: m[1].trim(), body: m[2].trim() });
	}
	return out;
}

const words = (s) => s.split(/\s+/).filter(Boolean).length;
// Real writing has lowercase letters: the all-capitals lines of the template do not count.
const written = (s, min) => words(s) >= min && /[a-z]/.test(s);
const cells = (l) => l.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
const SCORE = /^(10|[1-9])$/;

/** The ICE table under "Next 6 months": rows with Impact, Confidence and Ease scored 1 to 10, below a header that names them. */
export function iceTable(body) {
	const lines = body.split("\n").filter((l) => /^\s*\|.*\|\s*$/.test(l) && !/^\s*\|[\s:|-]+\|\s*$/.test(l));
	if (!lines.length) return [];
	const head = cells(lines[0]).map((h) => h.toLowerCase());
	const at = (f) => head.findIndex(f);
	const [i, c, e] = ["impact", "confidence", "ease"].map((w) => at((h) => h.includes(w)));
	const ice = at((h) => h === "ice" || h.startsWith("ice "));
	const watch = at((h) => /number|watch|metric/.test(h));
	if ([i, c, e].includes(-1)) return [];
	return lines
		.slice(1)
		.map(cells)
		.filter((r) => [i, c, e].every((k) => SCORE.test(r[k] || "")))
		.map((r) => ({ i: +r[i], c: +r[c], e: +r[e], ice: ice === -1 ? Number.NaN : Number(r[ice]), watch: watch === -1 ? "" : r[watch] || "" }));
}

/** Part 2 points from ROADMAP.md. */
export function scoreRoadmap(md) {
	const find = (w) => sections(md).find((s) => s.title.toLowerCase().includes(w));
	const rows = iceTable(find("next")?.body || "");
	const full = rows.length >= 3;
	return {
		vision: written(find("vision")?.body || "", 20) ? 5 : 0,
		ice: Math.min(rows.length, 3) * 5,
		math: full ? (rows.every((r) => r.ice === r.i * r.c * r.e) ? 5 : 0) + (rows.every((r, k) => k === 0 || rows[k - 1].ice >= r.ice) ? 5 : 0) : 0,
		watch: full && rows.every((r) => r.watch.length >= 5 && !/^(metric|tbd|n\/a|todo)$/i.test(r.watch)) ? 5 : 0,
		notnow: written(find("not now")?.body || "", 8) ? 5 : 0,
	};
}

/** The README is the candidate's own: it shows `flisk up` and has a section of 3 or more lines on what was hard. */
export function scoreReadme(readme) {
	const hard = sections(readme).find((s) => /hard|friction|problem|issue|learn/i.test(s.title));
	const lines = (hard?.body || "").split("\n").filter((l) => l.trim().length >= 3).length;
	return /flisk up\b/.test(readme) && !/^# Flisk task starter/m.test(readme) && lines >= 3 ? 10 : 0;
}

/** A reference GitHub turns into a "mentioned this" event on another repository's issue or pull request. */
export function crossRef(text, own) {
	const refs = [...text.matchAll(/github\.com\/([\w.-]+\/[\w.-]+)\/(?:issues|pull)\/\d+/gi), ...text.matchAll(/(?:^|[\s(])([\w.-]+\/[\w.-]+)#\d+/g)];
	return refs.some((m) => m[1].toLowerCase() !== own.toLowerCase());
}

export async function runChecks({ user, repo, start }, get = (u) => fetch(u)) {
	const json = async (u) => {
		const r = await get(u);
		if (!r.ok) throw new Error(`${r.status} ${u.replace(API, "")}`);
		return r.json();
	};
	const text = async (path, ref) => {
		const r = await get(`${RAW}/${user}/${repo}/${ref}/${path}`);
		return r.ok ? r.text() : "";
	};
	const info = await json(`${API}/repos/${user}/${repo}`);
	if (info.private) throw new Error("The repository is not public.");
	const ref = info.default_branch;
	const [tree, commits, runs] = await Promise.all([
		json(`${API}/repos/${user}/${repo}/git/trees/${ref}?recursive=1`),
		json(`${API}/repos/${user}/${repo}/commits?per_page=30`),
		json(`${API}/repos/${user}/${repo}/actions/runs?branch=${encodeURIComponent(ref)}&per_page=1`).catch(() => ({})),
	]);
	const paths = (tree.tree || []).map((f) => f.path);
	const has = (re) => paths.some((p) => re.test(p));
	const [readme, roadmap] = await Promise.all([text("README.md", ref), text("ROADMAP.md", ref)]);

	const own = `${user}/${repo}`;
	const startMs = Date.parse(`${start}T00:00:00Z`);
	const watched = WATCHED.filter((r) => r !== own.toLowerCase());
	const q = `author:${user} created:>=${start} ${watched.map((r) => `repo:${r}`).join(" ")}`;
	const contacted = await json(`${API}/search/issues?per_page=5&q=${encodeURIComponent(q)}`)
		.then((r) => r.total_count > 0)
		.catch(() => null);
	const recent = commits.filter((c) => Date.parse(c.commit.committer.date) >= startMs);

	const services = paths.filter((p) => p.endsWith("service.json")).length;
	const points = {
		fork: info.fork === true && (info.parent?.full_name || "").toLowerCase() === STARTER ? 10 : 0,
		stack: has(/(^|\/)\.flisk\/project\.json$/) ? Math.min(services, 5) * 4 : 0,
		readme: scoreReadme(readme),
		license: has(/^LICEN[CS]E(\.[a-z]+)?$/i) && has(/^NOTICE(\.[a-z]+)?$/i) ? 5 : 0,
		clean: !has(/(^|\/)\.env(\.(?!example$|sample$|template$)[^/]*)?$/) && !has(/(^|\/)node_modules\//) && !has(GENERATED) ? 5 : 0,
		...scoreRoadmap(roadmap),
		crossrefs: recent.some((c) => crossRef(c.commit.message || "", own)) ? 0 : 5,
		contact: contacted === false ? 5 : 0,
	};

	const deadline = deadlineOf(start);
	const gate = {
		started: !!deadline && Date.parse(info.created_at) >= startMs,
		inTime: !!deadline && commits.every((c) => Date.parse(c.commit.committer.date) <= deadline.getTime()),
	};
	const rows = ROWS.map(([key, group, label, max]) => ({ key, group, label, max, points: points[key], ok: points[key] === max }));
	const sum = (g) => rows.filter((r) => !g || r.group === g).reduce((n, r) => n + r.points, 0);
	const score = sum();
	const must = MUST.every((k) => points[k] === ROWS.find((r) => r[0] === k)[3]);
	const eligible = gate.started && gate.inTime;
	const last = (runs.workflow_runs || [])[0];
	return {
		score,
		parts: { technical: sum("technical"), product: sum("product"), conduct: sum("conduct") },
		rows,
		gate,
		deadline,
		status: !eligible ? "not-eligible" : score >= READY_AT && must ? "ready" : "not-ready",
		ready: eligible && score >= READY_AT && must,
		contactUnknown: contacted === null,
		ci: last ? { ok: last.conclusion === "success", url: last.html_url } : null,
		repoUrl: info.html_url,
		head: commits[0]?.sha,
	};
}
